cells={(r,c) for r,row in enumerate([[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]) for c,x in enumerate(row) if x}
motifs=[]
for r in range(3):
 for c in range(6):
  sub={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  hits=sub&cells
  if len(hits)>=3:
   miss=sub-hits
   color={0:1}.get(len(miss))
   # identify color by missing corner
   if len(miss)==1:
    corner=next(iter(miss)); color={(r,c):2,(r,c+1):4,(r+1,c):3,(r+1,c+1):5}[corner]
   motifs.append((r,c,hits,color))
[(r,c,len(h),color,sorted(h)) for r,c,h,color in motifs]

known=[m for m in motifs if m[3]!=5]
sols=[]
def rec(rem,chosen):
 if not rem:
  sols.append(chosen);return
 x=min(rem,key=lambda p:sum(p in h and h<=rem for _,_,h,_ in known))
 for m in known:
  if x in m[2] and m[2]<=rem:
   rec(rem-m[2],chosen+[m])
rec(cells,[])
len(sols), [[(m[0],m[1],m[3]) for m in s] for s in sols[:10]]

